Sure, here's the modified code to sort the array in descending order using the bubble sort algorithm:
```
#include <iostream>
#include <cstdlib>
using namespace std;
int main() {
    int arr[6];
    srand(time(NULL));
    for (int i = 0; i < 6; i++) {
        arr[i] = rand() % 100;
        cout << arr[i] << " ";
    }
    cout << endl;
    // Bubble sort algorithm
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5-i; j++) {
            if (arr[j] < arr[j+1]) {
                int temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
