wardrobe_length = 2; % meters
% Define optimization variables
x = optimvar('x', 3, 1, 'LowerBound', 0, 'UpperBound', room_width - bed_width - desk_width - wardrobe_width);
y = optimvar('y', 3, 1, 'LowerBound', 0, 'UpperBound', room_length - bed_length - desk_length - wardrobe_length);
% Define objective function
objfun = -((room_width - (x(1) + bed_width + x(2) + desk_width + x(3) + wardrobe_width)) * (room_length - (y(1) + bed_length + y(2) + desk_length + y(3) + wardrobe_length)));
% Define constraints
