          y(1) + y(2) + y(3) <= room_length - bed_length - desk_length - wardrobe_length];
% Solve optimization problem
problem = optimproblem('Objective', objfun, 'Constraints', constr);
[sol, fval] = solve(problem);
% Display optimal furniture arrangement
