	}
	for _, term := range f.Denominator {
		coefficient := term.Coefficient
		exponent := term.Exponent
		if term.Variable == "x" {
			coefficient *= math.Pow(x, exponent)
			exponent -= 1.0
			if exponent < 0 {
				coefficient = 0.0
			}
		}
		denominator += coefficient * math.Pow(x, exponent)
	}
	if math.IsNaN(numerator/denominator) {
		return limit(f, x+0.0001)
	}
	if math.IsInf(numerator/denominator, 0) {
		return math.NaN()
	}
	if numerator/denominator != numerator/denominator {
		return math.NaN()
	}
	return numerator / denominator
}
func limitLH(f Function, x float64) float64 {
	// Calculate the first derivative of the numerator and denominator
	numerator1 := Function{[]Term{
		{f.Numerator[0].Coefficient * f.Numerator[0].Exponent, "x", f.Numerator[0].Exponent - 1},
		{f.Numerator[1].Coefficient * f.Numerator[1].Exponent, "x", f.Numerator[1].Exponent - 1},
		{f.Numerator[2].Coefficient, "", 0},
	}, []Term{
		{f.Denominator[0].Coefficient * f.Denominator[0].Exponent, "x", f.Denominator[0].Exponent - 1},
		{f.Denominator[1].Coefficient * f.Denominator[1].Exponent, "x", f.Denominator[1].Exponent - 1},
		{f.Denominator[2].Coefficient, "", 0},
	}}
	denominator1 := Function{[]Term{
		{f.Numerator[0].Coefficient * f.Numerator[0].Exponent, "x", f.Numerator[0].Exponent - 1},
		{f.Numerator[1].Coefficient * f.Numerator[1].Exponent, "x", f.Numerator[1].Exponent - 1},
		{f.Numerator[2].Coefficient, "", 0},
	}, []Term{
		{f.Denominator[0].Coefficient * f.Denominator[0].Exponent, "x", f.Denominator[0].Exponent - 1},
		{f.Denominator[1].Coefficient * f.Denominator[1].Exponent, "x", f.Denominator[1].Exponent - 1},
		{f.Denominator[2].Coefficient, "", 0},
	}}
	limit1 := limit(Function{numerator1.Numerator, numerator1.Denominator}, x) / limit(Function{denominator1.Numerator, denominator1.Denominator}, x)
	// Calculate the second derivative of the numerator and denominator
	numerator2 := Function{[]Term{
		{numerator1.Numerator[0].Coefficient * numerator1.Numerator[0].Exponent, "x", numerator1.Numerator[0].Exponent - 1},
		{numerator1.Numerator[1].Coefficient * numerator1.Numerator[1].Exponent, "x", numerator1.Numerator[1].Exponent - 1},
	}, []Term{
		{numerator1.Denominator[0].Coefficient * numerator1.Denominator[0].Exponent, "x", numerator1.Denominator[0].Exponent - 1},
		{numerator1.Denominator[1].Coefficient * numerator1.Denominator[1].Exponent, "x", numerator1.Denominator[1].Exponent - 1},
	}}
	denominator2 := Function{[]Term{
		{denominator1.Numerator[0].Coefficient * denominator1.Numerator[0].Exponent, "x", denominator1.Numerator[0].Exponent - 1},
		{denominator1.Numerator[1].Coefficient * denominator1.Numerator[1].Exponent, "x", denominator1.Numerator[1].Exponent - 1},
	}, []Term{
		{denominator1.Denominator[0].Coefficient * denominator1.Denominator[0].Exponent, "x", denominator1.Denominator[0].Exponent - 1},
		{denominator1.Denominator[1].Coefficient * denominator1.Denominator[1].Exponent, "x", denominator1.Denominator[1].Exponent - 1},
	}}
	limit2 := limit(Function{numerator2.Numerator, numerator2.Denominator}, x) / limit(Function{denominator2.Numerator, denominator2.Denominator}, x)
	// Calculate the final limit
	return limit1 - (limit2 / limit1)
}
