To implement RSA encryption and decryption in JavaScript, you can use the following code:
```
// Generate a public-private key pair
function generateRSAKeyPair(keySize) {
  const p = generatePrimeNumber(keySize / 2);
  const q = generatePrimeNumber(keySize / 2);
  const n = p * q;
  const phi = (p - 1) * (q - 1);
  let e = 65537;
  while (gcd(e, phi) !== 1) {
    e++;
  }
  const d = modInverse(e, phi);
  return {
    publicKey: { n, e },
    privateKey: { n, d },
  };
}
// Encrypt a message with the recipient's public key
function encryptRSA(message, publicKey) {
  const { n, e } = publicKey;
  let encryptedMessage = '';
  for (let i = 0; i < message.length; i++) {
    const charCode = message.charCodeAt(i);
    const encryptedCharCode = modPow(charCode, e, n);
    encryptedMessage += String.fromCharCode(encryptedCharCode);
  }
  return encryptedMessage;
}
// Decrypt the encrypted message with your private key
function decryptRSA(encryptedMessage, privateKey) {
  const { n, d } = privateKey;
  let decryptedMessage = '';
  for (let i = 0; i < encryptedMessage.length; i++) {
    const charCode = encryptedMessage.charCodeAt(i);
    const decryptedCharCode = modPow(charCode, d, n);
    decryptedMessage += String.fromCharCode(decryptedCharCode);
  }
  return decryptedMessage;
}
// Helper functions
function generatePrimeNumber(bitLength) {
  const min = 2 ** (bitLength - 1);
  const max = 2 ** bitLength - 1;
  while (true) {
    const primeCandidate = getRandomNumber(min, max);
    if (isPrime(primeCandidate)) {
      return primeCandidate;
    }
  }
}
function getRandomNumber(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}
function isPrime(num) {
  if (num === 2) {
    return true;
  }
  if (num < 2 || num % 2 === 0) {
    return false;
  }
  const maxDivisor = Math.sqrt(num);
  for (let i = 3; i <= maxDivisor; i += 2) {
    if (num % i === 0) {
      return false;
    }
  }
  return true;
}
function gcd(a, b) {
  if (a === 0) {
    return b;
  }
  return gcd(b % a, a);
}
function modInverse(a, m) {
  const [g, x] = extendedEuclideanAlgorithm(a, m);
  if (g !== 1) {
    throw new Error('modular inverse does not exist');
  }
  return x % m;
}
function extendedEuclideanAlgorithm(a, b) {
  if (a === 0) {
    return [b, 0, 1];
  }
  const [g, x1, y1] = extendedEuclideanAlgorithm(b % a, a);
  const x = y1 - Math.floor(b / a) * x1;
  const y = x1;
  return [g, x, y];
}
function modPow(base, exponent, modulus) {
  if (modulus === 1) {
    return 0;
  }
  let result = 1;
  base = base % modulus;
  while (exponent > 0) {
    if (exponent % 2 === 1) {
      result = (result * base) % modulus;
    }
    exponent = Math.floor(exponent / 2);
    base = (base * base) % modulus;
  }
  return result;
}
