Relationship getRelationship(const WordPair& pair) {
    if (pair.first == pair.second) {
        return SAME;
    } else if (isSynonym(pair.first, pair.second)) {
        return SYNONYM;
    } else if (isAntonym(pair.first, pair.second)) {
        return ANTTONYM;
    } else if (isHypernym(pair.first, pair.second)) {
        return HYPERNYM;
    } else if (isHyponym(pair.first, pair.second)) {
        return HYPONYM;
    } else if (isMeronym(pair.first, pair.second)) {
