void generatePuzzle(const std::vector<WordPair>& dataset) {
    // select a random word pair
    int index = rand() % dataset.size();
    const WordPair& pair = dataset[index];
    // get the correct relationship
    Relationship correctRelationship = getRelationship(pair);
    // shuffle the possible relationships
    std::vector<Relationship> possibleRelationships = {SAME, SYNONYM, ANTTONYM, HYPERNYM, HYPONYM, MERONYM, HOLONYM, ASSOCIATION, OTHER};
    std::random_shuffle(possibleRelationships.begin(), possibleRelationships.end());
    // present the question and choices
