    for (int i = 0; i < possibleRelationships.size(); i++) {
        std::cout << i+1 << ". " << toString(possibleRelationships[i]) << std::endl;
    }
    // get the user's answer
    int answer;
    std::cin >> answer;
    // check if the answer is correct
    if (answer == indexOf(correctRelationship, possibleRelationships) + 1) {
        std::cout << "Correct!" << std::endl;
    } else {
