To integrate a backend server into a mobile app developed using C++, you can use a networking library such as libcurl. 
Here's an example code demonstrating how to send and receive data from the server using libcurl:
```
#include <iostream>
#include <curl/curl.h>
int main()
{
    CURL *curl;
    CURLcode res;
    std::string readBuffer;
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/api");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "data=some_data");
        // Set the write callback function to receive the response from the server
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](char *data, size_t size, size_t nmemb, std::string *buffer) -> size_t {
            buffer->append(data, size * nmemb);
            return size * nmemb;
        });
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
        }
        /* always cleanup */
        curl_easy_cleanup(curl);
    }
    std::cout << readBuffer << std::endl;
    return 0;
}
```
