    recognitionRequest = SFSpeechAudioBufferRecognitionRequest()
    guard let recognitionRequest = recognitionRequest else { fatalError("Unable to create recognition request") }
    recognitionRequest.shouldReportPartialResults = true
    recognitionTask = speechRecognizer?.recognitionTask(with: recognitionRequest) { result, error in
      if let result = result {
        let bestString = result.bestTranscription.formattedString
        // Check for laughter using HaHa algorithm
        let laughterDetected = bestString.contains("HaHa") || bestString.contains("hahaha")
        if laughterDetected {
          // Perform data analysis and visualization
        }
      }
    }
    let recordingCallback: AVAudioNodeTapBlock = { buffer, _ in
      self.recognitionRequest?.append(buffer)
    }
    inputNode.installTap(onBus: 0, bufferSize: 1024, format: recordingFormat, block: recordingCallback)
    try audioSession.setCategory(.record)
    try audioSession.setMode(.measurement)
    try audioSession.setActive(true, options: .notifyOthersOnDeactivation)
    audioEngine.prepare()
    try audioEngine.start()
  }
  func stopRecording() {
    audioEngine.stop()
    audioEngine.inputNode.removeTap(onBus: 0)
    recognitionRequest?.endAudio()
    recognitionTask?.cancel()
  }
}
