public class MentalHealthAnalysis {
    private static final String CSV_FILE_PATH = "data.csv";
    public static void main(String[] args) {
        List<DataPoint> dataPoints = readDataFromCSV(CSV_FILE_PATH);
        List<DataPoint> cleanedDataPoints = cleanData(dataPoints);
