    private static List<DataPoint> readDataFromCSV(String filePath) {
        List<DataPoint> dataPoints = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] values = line.split(",");
                DataPoint dataPoint = new DataPoint(values[0], values[1], Double.parseDouble(values[2]));
                dataPoints.add(dataPoint);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return dataPoints;
