    private static List<DataPoint> cleanData(List<DataPoint> dataPoints) {
        List<DataPoint> cleanedDataPoints = new ArrayList<>();
        for (DataPoint dataPoint : dataPoints) {
            if (dataPoint.getMentalHealthScore() != null) {
                cleanedDataPoints.add(dataPoint);
            }
        }
        return cleanedDataPoints;
    }
    private static Map<String, List<Double>> groupDataByFoodType(List<DataPoint> dataPoints) {
        Map<String, List<Double>> groupedData = new HashMap<>();
        for (DataPoint dataPoint : dataPoints) {
            String foodType = dataPoint.getFoodType();
            Double mentalHealthScore = dataPoint.getMentalHealthScore();
            if (!groupedData.containsKey(foodType)) {
                groupedData.put(foodType, new ArrayList<>());
            }
            groupedData.get(foodType).add(mentalHealthScore);
        }
        return groupedData;
    }
    private static Map<String, Double[]> calculateStatistics(Map<String, List<Double>> groupedData) {
        Map<String, Double[]> statistics = new HashMap<>();
        for (Map.Entry<String, List<Double>> entry : groupedData.entrySet()) {
            String foodType = entry.getKey();
            List<Double> mentalHealthScores = entry.getValue();
            double[] mentalHealthScoresArray = mentalHealthScores.stream().mapToDouble(Double::doubleValue).toArray();
            Double mean = calculateMean(mentalHealthScoresArray);
            Double median = calculateMedian(mentalHealthScoresArray);
            Double standardDeviation = calculateStandardDeviation(mentalHealthScoresArray);
            statistics.put(foodType, new Double[]{mean, median, standardDeviation});
        }
        return statistics;
    }
    private static Double calculateMean(double[] values) {
        double sum = 0;
        for (double value : values) {
            sum += value;
        }
        return sum / values.length;
    }
    private static Double calculateMedian(double[] values) {
        int middle = values.length / 2;
        if (values.length % 2 == 1) {
            return values[middle];
        } else {
            return (values[middle - 1] + values[middle]) / 2.0;
        }
    }
    private static Double calculateStandardDeviation(double[] values) {
        double mean = calculateMean(values);
        double sum = 0;
        for (double value : values) {
            sum += Math.pow(value - mean, 2);
        }
        return Math.sqrt(sum / values.length);
    }
